#include "Engine.h"
#include <cmath>
namespace {
juce::Result copyClip(const StudioTrack& track,vocal::AudioChannels& result){
    const int begin=juce::jlimit(0,track.audio.getNumSamples(),static_cast<int>(std::llround(track.trimIn*track.sourceRate)));
    const int end=juce::jlimit(begin,track.audio.getNumSamples(),static_cast<int>(std::llround(track.trimOut*track.sourceRate)));
    if(end-begin<1024)return juce::Result::fail(juce::String::fromUTF8("Clip quá ngắn để dò hoặc chỉnh tone."));
    if(static_cast<juce::int64>(end-begin)*track.audio.getNumChannels()*4>256LL*1024*1024)return juce::Result::fail(juce::String::fromUTF8("Chia clip thành đoạn ngắn hơn: giới hạn xử lý tone là 256 MB audio mỗi lần."));
    result.resize(static_cast<std::size_t>(track.audio.getNumChannels()));for(int c=0;c<track.audio.getNumChannels();++c)result[static_cast<std::size_t>(c)].assign(track.audio.getReadPointer(c,begin),track.audio.getReadPointer(c,end));return juce::Result::ok();
}
void copyMixState(const StudioTrack& from,StudioTrack& to){to.start=from.start;to.gainDb=from.gainDb.load();to.pan=from.pan.load();to.mute=from.mute.load();to.solo=from.solo.load();}
}
void StudioEngine::replaceTrack(int index,std::unique_ptr<StudioTrack> track){if(!juce::isPositiveAndBelow(index,static_cast<int>(tracks.size()))||!track)return;withAudioStopped([&]{tracks[static_cast<std::size_t>(index)]=std::move(track);resetProcessing();});}
juce::Result StudioEngine::analyseTrack(int index,vocal::PitchAnalysis& analysis,std::atomic<bool>& cancel,std::atomic<float>& progress){
    if(!juce::isPositiveAndBelow(index,static_cast<int>(tracks.size())))return juce::Result::fail(juce::String::fromUTF8("Chọn một track trước."));
    const auto& source=*tracks[static_cast<std::size_t>(index)];vocal::AudioChannels audio;auto result=copyClip(source,audio);if(result.failed())return result;analysis=vocal::analysePitch(audio,source.sourceRate,source.vocal,cancel,progress);return cancel.load()?juce::Result::fail(juce::String::fromUTF8("Đã hủy dò tone.")):juce::Result::ok();
}
juce::Result StudioEngine::renderPitchTrack(int index,const vocal::PitchOptions& requested,std::unique_ptr<StudioTrack>& result,std::atomic<bool>& cancel,std::atomic<float>& progress){
    if(isPlaying()||isRecording()||!juce::isPositiveAndBelow(index,static_cast<int>(tracks.size())))return juce::Result::fail(juce::String::fromUTF8("Dừng phát/thu và chọn track cần xử lý."));
    const auto& source=*tracks[static_cast<std::size_t>(index)];auto options=requested;if(options.correction>0&&isAntaresActive())return juce::Result::fail(juce::String::fromUTF8("Antares đang hoạt động. Bypass Antares trước khi dùng chỉnh phô ngoại tuyến để tránh chỉnh hai lần gây méo."));if(options.correction>0&&!source.vocal)return juce::Result::fail(juce::String::fromUTF8("Chỉnh phô chỉ dùng cho giọng đơn. Đánh dấu Track giọng hát; không dùng lên beat hoặc bè nhiều giọng."));
    vocal::AudioChannels input;auto ready=copyClip(source,input);if(ready.failed())return ready;vocal::PitchAnalysis analysis;
    if(options.correction>0||(source.vocal&&options.preserveFormants)){analysis=vocal::analysePitch(input,source.sourceRate,true,cancel,progress);if(cancel.load())return juce::Result::fail(juce::String::fromUTF8("Đã hủy xử lý tone."));if(options.correction>0&&analysis.voicedFraction<.1)return juce::Result::fail(juce::String::fromUTF8("Không tìm thấy đủ giọng đơn rõ để chỉnh phô."));if(options.correction>0&&options.autoKey){vocal::PitchAnalysis keyAnalysis=analysis;
            for(const auto& candidate:tracks){if(candidate->vocal||candidate->mute.load())continue;vocal::AudioChannels beat;if(copyClip(*candidate,beat).failed())continue;auto detected=vocal::analysePitch(beat,candidate->sourceRate,false,cancel,progress);if(cancel.load())return juce::Result::fail(juce::String::fromUTF8("Đã hủy dò tone beat."));if(detected.tonic>=0&&detected.keyConfidence>=.5){keyAnalysis=std::move(detected);break;}}
            if(keyAnalysis.tonic<0||keyAnalysis.keyConfidence<.5)return juce::Result::fail(juce::String::fromUTF8("Chưa đủ dữ liệu để chọn tone tự động. Chọn trưởng/thứ hoặc Chromatic bằng tay."));options.tonic=keyAnalysis.tonic;options.minor=keyAnalysis.minor;}}
    auto output=vocal::processPitch(input,source.sourceRate,options,source.vocal?&analysis:nullptr,cancel,progress);if(cancel.load()||output.empty())return juce::Result::fail(juce::String::fromUTF8("Đã hủy; bản cũ không thay đổi."));
    float peak=0;for(const auto& channel:output)for(float x:channel)peak=juce::jmax(peak,std::abs(x));const float gain=peak>.98f?.98f/peak:1;
    const auto target=source.file.getSiblingFile(source.file.getFileNameWithoutExtension()+"_Pitch.wav").getNonexistentSibling();juce::TemporaryFile temporary(target);auto stream=temporary.getFile().createOutputStream();if(!stream)return juce::Result::fail(juce::String::fromUTF8("Không tạo được file xử lý tone."));
    juce::WavAudioFormat wav;std::unique_ptr<juce::AudioFormatWriter> writer(wav.createWriterFor(stream.get(),source.sourceRate,static_cast<unsigned int>(output.size()),24,{},0));if(!writer)return juce::Result::fail("WAV writer failed");stream.release();juce::AudioBuffer<float> block(static_cast<int>(output.size()),4096);
    for(std::size_t offset=0;offset<output[0].size()&&!cancel.load();offset+=4096){const int n=static_cast<int>(juce::jmin<std::size_t>(4096,output[0].size()-offset));for(int c=0;c<block.getNumChannels();++c)for(int i=0;i<n;++i)block.setSample(c,i,output[static_cast<std::size_t>(c)][offset+i]*gain);if(!writer->writeFromAudioSampleBuffer(block,0,n))return juce::Result::fail(juce::String::fromUTF8("Không ghi đủ bản xử lý tone."));}writer.reset();if(cancel.load())return juce::Result::fail(juce::String::fromUTF8("Đã hủy; bản gốc được giữ nguyên."));if(!temporary.overwriteTargetFileWithTemporary())return juce::Result::fail("Cannot finalize pitch render");
    ready=readTrack(target,source.vocal,result);if(ready.failed())return ready;copyMixState(source,*result);result->name=source.name+" [Pitch]";result->originalFile=source.originalFile;result->originalTrimIn=source.file==source.originalFile?source.trimIn:source.originalTrimIn;result->originalTrimOut=source.file==source.originalFile?source.trimOut:source.originalTrimOut;return juce::Result::ok();
}
juce::Result StudioEngine::restoreOriginalTrack(int index,std::unique_ptr<StudioTrack>& result){if(!juce::isPositiveAndBelow(index,static_cast<int>(tracks.size())))return juce::Result::fail("No selected track");const auto& source=*tracks[static_cast<std::size_t>(index)];auto ready=readTrack(source.originalFile,source.vocal,result);if(ready.failed())return ready;copyMixState(source,*result);result->trimIn=juce::jlimit(0.0,result->trimOut,source.originalTrimIn);result->trimOut=juce::jlimit(result->trimIn,result->trimOut,source.originalTrimOut);return juce::Result::ok();}
